const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";

const [alive, loginOnly] = await Promise.all([
  fs.readFile(S+"\\_GIG_ALL_ALIVE.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_LOGINONLY_RESULT.json","utf8").then(JSON.parse).catch(()=>[])
]);

// A 组：能看到活（51，去掉 freelancer.in）
const A = alive.filter(a=>String(a.host)!=="freelancer.in").map(a=>({
  name:a.name, host:a.host, url:a.url, group:"能看到活", verdict:a.verdict, cards:a.cards, note:"列表页实测可见项目"
}));

// B 组：需登录但真实存在
const B = loginOnly.filter(o=>o.status==="存在").map(o=>({
  name:o.name, host:o.host, url:"https://"+o.host, group:"需注册", verdict:"", cards:0, note:o.note
}));

// 合并去重
const merged = new Map();
for (const x of [...A, ...B]) {
  const h = String(x.host).toLowerCase().replace(/^www\./,"");
  if (!merged.has(h)) merged.set(h, x);
}
const all = [...merged.values()];

// 分类
const TYPE = {
  "🌍 综合接单大平台": ["freelancer.com","upwork.com","toptal.com","peopleperhour.com","guru.com","truelancer.com","freelancehunt.com","fiverr.com","dribbble.com"],
  "🇨🇳 中文接单": ["zbj.com","epink","epwk.com","proginn.com","shixian.com","yuanjisong.com","zb.oschina.net","tezign.com"],
  "🧪 UX测试/用户调研": ["prolific.com","userfeel.com","userlytics.com","validately.com","usabilityhub.com","userzoom.com","testingtime.com","playtestcloud.com","usertesting.com"],
  "📝 转录/字幕": ["scribie.com","castingwords.com","gotranscript.com","rev.com","transcribeme.com","transcriptionhub.com"],
  "🌐 翻译": ["smartcat.com","unbabel.com","onehourtranslation.com","textroyal.com","proz.com"],
  "✍️ 写作/内容": ["writeraccess.com","crowdcontent.com","scripted.com","ndash.com","iwriter.com","constant-content.com","textbroker.com"],
  "🎓 家教/辅导": ["varsitytutors.com","studypool.com","cambly.com","preply.com","wyzant.com","tutorhunt.com"],
  "🤖 AI训练/标注": ["mercor.com","alignerr.com","outlier.ai","dataannotation.tech","toloka.ai","microworkers.com","remotasks.com","appen.com","scale.com","mturk.com","clickworker.com","oneforma.com","figure-eight.com"],
  "💰 漏洞赏金": ["hackenproof.com","synack.com","cobalt.io","bugbase.in"],
  "💼 专业服务": ["glg.com","thirdbridge.com","tegus.com","zintro.com","ttec.com","arise.com","concentrix.com"],
  "🎨 设计/创意": ["workingnotworking.com","99designs.com","designcrowd.com"],
  "📍 实地任务": ["streetbees.com","premise.com"],
  "💰 微任务奖励": ["prizerebel.com"],
};
const assign = h => {
  const x = String(h).toLowerCase();
  for (const [t,ks] of Object.entries(TYPE)) if (ks.some(k=>x.includes(k.split('.')[0]))) return t;
  return "其他";
};
const groups = {};
for (const a of all) { const t=assign(a.host); (groups[t] ??= []).push(a); }

await fs.writeFile(S+"\\_GIG_MASTER.json", JSON.stringify({total:all.length, groups},null,1), "utf8");
return { total: all.length, seeAlive: A.length, loginOnly: B.length, groups: Object.entries(groups).map(([k,v])=>k+":"+v.length) };
